/* 组件就绪后执行 */
Eam.registerInit(async function(){
/* 公共可访问性、主题与模块导航交互；不构建业务页面。 */
(()=>{const s=Eam.s,header=document.querySelector('.appbar'),aside=document.getElementById('module-nav'),main=document.querySelector('main');main.id='main-content';const skip=document.createElement('a');skip.href='#main-content';skip.className='skip-link';skip.textContent='跳到业务内容';document.body.prepend(skip);main.tabIndex=-1;
const theme=document.createElement('select');theme.id='ui-theme';theme.setAttribute('aria-label','界面主题');for(const [value,label]of [['light','浅色'],['dark','深色'],['system','跟随系统']])theme.add(new Option(label,value));const themeLabel=document.createElement('label');themeLabel.className='field';themeLabel.textContent='界面主题';themeLabel.append(theme);document.querySelector('.review-panel').prepend(themeLabel);let preference=sessionStorage.getItem('eam-ui-theme')||'light';const scheme=matchMedia('(prefers-color-scheme:dark)');function applyTheme(){document.documentElement.dataset.theme=preference==='system'?(scheme.matches?'dark':'light'):preference;document.documentElement.dataset.bsTheme=document.documentElement.dataset.theme;theme.value=preference;}theme.onchange=()=>{preference=theme.value;sessionStorage.setItem('eam-ui-theme',preference);applyTheme();};scheme.addEventListener('change',applyTheme);applyTheme();
if(document.body.dataset.page!=='platform'){const toggle=document.createElement('button');toggle.id='nav-toggle';toggle.type='button';toggle.textContent='模块菜单';toggle.setAttribute('aria-controls','module-nav');toggle.setAttribute('aria-expanded','true');header.querySelector('.controls').prepend(toggle);const close=document.createElement('button');close.type='button';close.className='drawer-close';close.textContent='关闭模块菜单';aside.prepend(close);const scrim=document.createElement('button');scrim.className='nav-scrim';scrim.type='button';scrim.tabIndex=-1;scrim.setAttribute('aria-label','关闭模块菜单遮罩');document.body.append(scrim);const isNarrow=()=>document.body.classList.contains('mobile-preview')||matchMedia('(max-width:1024px)').matches;function closeDrawer(){document.body.classList.remove('nav-open');main.inert=false;header.inert=false;aside.removeAttribute('role');aside.removeAttribute('aria-modal');toggle.setAttribute('aria-expanded',String(!isNarrow()&&!document.body.classList.contains('sidebar-collapsed')));}toggle.onclick=()=>{if(isNarrow()){document.body.classList.add('nav-open');main.inert=true;header.inert=true;aside.setAttribute('role','dialog');aside.setAttribute('aria-modal','true');aside.setAttribute('aria-label','设备管理模块菜单');toggle.setAttribute('aria-expanded','true');close.focus();}else{document.body.classList.toggle('sidebar-collapsed');toggle.setAttribute('aria-expanded',String(!document.body.classList.contains('sidebar-collapsed')));}};close.onclick=scrim.onclick=()=>{closeDrawer();toggle.focus();};document.addEventListener('keydown',e=>{if(!document.body.classList.contains('nav-open'))return;if(e.key==='Escape'){e.preventDefault();closeDrawer();toggle.focus();}if(e.key==='Tab'){const buttons=[...aside.querySelectorAll('button:not(:disabled)')],first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});matchMedia('(max-width:1024px)').addEventListener('change',closeDrawer);document.getElementById('view-toggle').addEventListener('click',closeDrawer);closeDrawer();}
Eam.Tabs.enhance(document);
document.addEventListener('click',event=>{const toggle=event.target.closest('[data-filter-toggle]');if(!toggle)return;const panel=Eam.find(toggle.closest('[data-instance]')||toggle.closest('main')||document,toggle.dataset.filterToggle);if(!panel)return;EamUiComponents.openFilter(panel,toggle);});
function decorate(){for(const badge of document.querySelectorAll('.problem-badge,.tag')){const status=badge.dataset.state||badge.textContent.trim();const tones={technical_complete:'warning',accepted:'warning',pending_review:'warning',pending_verification:'warning',open:'warning',paused:'warning',rectifying:'info',in_progress:'info',triaged:'info',confirmed:'danger',unresolved:'danger',archived:'success',resolved:'info',withdrawn:'secondary',low:'secondary',not_applicable:'secondary',closed:'success',completed:'success',normal:'success',active:'success',approved:'success',high:'danger',critical:'danger',blocked:'danger',failed:'danger',pending:'warning',submitted:'warning',restored:'warning',medium:'warning',review:'warning',draft:'secondary',unknown:'secondary',cancelled:'secondary',running:'info',assigned:'info',executing:'info','正常':'success','在用':'success','已关闭':'success','待审核':'warning','待验收':'warning','故障':'danger','高':'danger','中':'warning'};const tone=tones[status]||'secondary';badge.classList.remove('problem-badge','tag','tag-danger');badge.classList.add('badge','text-bg-'+tone);}if(document.body.dataset.layout==='list'){main.classList.add('business-list-page');for(const panel of main.querySelectorAll(':scope>[data-component=list-panel]'))panel.classList.add('business-list-panel');}for(const b of document.querySelectorAll('main button,dialog button,.appbar button')){if(b.matches('.stat-card,[data-tab]'))continue;if(!b.classList.contains('btn'))b.classList.add('btn','btn-sm',b.closest('.appbar')?'btn-outline-light':b.classList.contains('primary')?'btn-primary':b.matches('.row-link,.work-link')?'btn-link':'btn-outline-secondary');}for(const el of document.querySelectorAll('main input:not([type=checkbox]):not([type=radio]):not([type=range]),dialog input:not([type=checkbox]):not([type=radio]):not([type=range]),main textarea,dialog textarea'))el.classList.add('form-control');for(const el of document.querySelectorAll('main select,dialog select'))el.classList.add('form-select');for(const b of document.querySelectorAll('main button,dialog button')){if(!/^(删除|移除|停用|确认报废)/.test(b.textContent.trim()))continue;if(b.matches('.stat-card,[data-tab]'))continue;if(!b.classList.contains('btn'))b.classList.add('btn','btn-sm');for(const c of [...b.classList])if(/^btn-outline/.test(c))b.classList.remove(c);b.classList.add('btn-danger');}EamUiComponents.decorateTables();EamUiComponents.decoratePagination();}
const compact=()=>{const mobile=document.body.classList.contains('mobile-preview')||matchMedia('(max-width:760px)').matches;for(const id of ['ledger-metrics-panel']){const panel=document.getElementById(id);if(panel)panel.open=!mobile;}};compact();matchMedia('(max-width:760px)').addEventListener('change',compact);document.getElementById('view-toggle')?.addEventListener('click',()=>queueMicrotask(compact));document.addEventListener('click',event=>{const summary=event.target.closest('.row-more>summary,.ledger-more>summary');for(const menu of document.querySelectorAll('.row-more[open],.ledger-more[open]'))if(!menu.contains(event.target))menu.open=false;if(summary){const details=summary.parentElement;requestAnimationFrame(()=>{if(!details.open)return;const rect=summary.getBoundingClientRect(),menu=details.querySelector('.row-action-menu,.ledger-menu');if(!menu)return;const box=menu.getBoundingClientRect();details.style.setProperty('--menu-left',Math.max(8,Math.min(rect.right-170,innerWidth-178))+'px');details.style.setProperty('--menu-top',Math.max(8,Math.min(rect.bottom+4,innerHeight-box.height-8))+'px');});}});const closeRowMenus=()=>document.querySelectorAll('.row-more[open],.ledger-more[open]').forEach(e=>e.open=false);main.addEventListener('scroll',closeRowMenus,{passive:true,capture:true});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeRowMenus();});for(const dialog of document.querySelectorAll('dialog')){let savedScroll=0;dialog.addEventListener('beforetoggle',e=>{if(e.newState==='open')savedScroll=main.scrollTop;});dialog.addEventListener('toggle',e=>{if(e.newState==='closed')requestAnimationFrame(()=>{main.scrollTop=savedScroll;});});}decorate();new MutationObserver(decorate).observe(main,{childList:true,subtree:true});for(const dialog of document.querySelectorAll('dialog'))if(!dialog.hasAttribute('aria-label')&&!dialog.hasAttribute('aria-labelledby')){const h=dialog.querySelector('h2');if(h){h.id ||= dialog.id+'-heading';dialog.setAttribute('aria-labelledby',h.id);}}
})();

});
